mapper.select:
select eb.id, lb.source_code businessCode, lb.outstock_id outStockId, lb.transport_no transportNo, eb.status, lb.shop_id shopId, lb.shop_name shopName, lb.to_country toCountry, lc.fee_rule feeRule, lbc.id logisticsBillCostId, lbc.currency, lbc.reconciliation_status actualBillStatus, lbd.track_status transportStatus, lbd.sign_time signTime, eb.confirm_time confirmTime, eb.create_time createTime, lb.channel_id logisticsChannelId, eb.logistics_bill_id from first_mile_estimated_bill eb inner join logistics_bill lb on eb.logistics_bill_id = lb.id and eb.is_deleted = false left join logistics_channel lc on lb.channel_id = lc.id left join logistics_bill_detail lbd on lb.id = lbd.main_id and lbd.is_deleted = false left join logistics_bill_cost lbc on lbc.logistics_bill_id = lb.id and lbc.is_deleted = false
eb.id in
#{id}

select eb.id, lb.source_code businessCode, lb.outstock_id outStockId, lb.transport_no transportNo, eb.status, lb.shop_id shopId, lb.shop_name shopName, lb.to_country toCountry, lc.fee_rule feeRule, lbc.id logisticsBillCostId, lbc.currency, lbc.reconciliation_status actualBillStatus, lbd.track_status transportStatus, lbd.sign_time signTime, eb.confirm_time confirmTime, eb.create_time createTime, lb.channel_id logisticsChannelId, eb.logistics_bill_id from first_mile_estimated_bill eb inner join logistics_bill lb on eb.logistics_bill_id = lb.id and eb.is_deleted = false left join logistics_channel lc on lb.channel_id = lc.id left join logistics_bill_detail lbd on lb.id = lbd.main_id and lbd.is_deleted = false left join logistics_bill_cost lbc on lbc.logistics_bill_id = lb.id and lbc.is_deleted = false
eb.is_deleted = false
and eb.logistics_bill_id in
#{id}
and eb.status = #{status}

select fmeb.logistics_bill_id logisticsBillId, tcc.dict_cost_attribution dictCostAttribution, tcc.dict_cost_category dictCostCategory, sum(tcd.cost_value) costValue from first_mile_estimated_bill fmeb inner join logistics_bill_cost lbc on fmeb.logistics_bill_id = lbc.logistics_bill_id left join tms_cost_detail tcd on lbc.id = tcd.main_id and tcd.is_deleted = false left join tms_cfg_cost tcc on tcd.cfg_cost_id = tcc.id
tcc.dict_cost_attribution = 'firstMile' and tcd.type = 'estimated' and fmeb.logistics_bill_id in
#{id}
group by fmeb.logistics_bill_id, tcc.dict_cost_attribution, tcc.dict_cost_category;

select count(1)
from first_mile_estimated_bill eb
    left join logistics_bill_cost lbc on lbc.logistics_bill_id = eb.logistics_bill_id and lbc.is_deleted = false

    eb.is_deleted = false

        and lbc.reconciliation_status = #{actualStatus}


        and eb.status = #{estimatedStatus}
